SELECT pi.system_id AS systemId, pi.object_id AS objectId, pi.user_id AS userId FROM eval_patrol_inspection pi INNER JOIN ( SELECT system_id, object_id, MAX(create_time) AS max_create_time FROM eval_patrol_inspection WHERE deleted = 0 AND system_id IS NOT NULL AND object_id IS NOT NULL
AND system_id IN
#{sid}
AND object_id IN
#{oid}
GROUP BY system_id, object_id ) latest ON pi.system_id = latest.system_id AND pi.object_id = latest.object_id AND pi.create_time = latest.max_create_time WHERE pi.deleted = 0 AND pi.system_id IS NOT NULL AND pi.object_id IS NOT NULL
